HAL_I2C_IsDeviceReady.exampleCode:
/* 先探测器件在不在，比直接收发更容易定位问题 */
if (HAL_I2C_IsDeviceReady(&hi2c1, 0x50 << 1, 3, 100) == HAL_OK)
{
  /* 器件在线 */
}
else
{
  /* 没应答：查接线、上拉电阻、地址 */
}

HAL_I2C_Master_Transmit.exampleCode:
uint8_t cmd[2] = {0x01, 0x02};

/* 主机阻塞发送，DevAddress 同样要左移一位 */
HAL_I2C_Master_Transmit(&hi2c1, 0x50 << 1, cmd, sizeof(cmd), 100);
